#include <author_parameters.h>
#include <plan_manage/scan_replan_fsm.h>
#include <cassert>
#include <iostream>
int main(){ScanConfig c{};c.resolution=double(float(.05));c.body_length=.5794;c.body_width=.328;c.body_to_ground=.4;c.body_center_x=.0503;c.body_z_min=-.448;c.body_z_max=.057;c.max_step_up=.15;c.max_step_down=.15;c.max_slope=1.;c.max_velocity=1.;c.max_acceleration=1.;c.max_yaw_rate=.8;c.max_yaw_acceleration=2.;c.sample_dt=.05;c.planning_horizon=3.5;c.max_reverse_velocity=1.;c.max_lateral_velocity=1.;auto n=scan_planner::authorParameters(c);scan_planner::SCANReplanFSM f;f.init(n);auto odom=std::make_shared<nav_msgs::Odometry>();odom->pose.pose.position.z=.4;odom->pose.pose.orientation.w=1.;f.onOdometry(odom);auto path=std::make_shared<nav_msgs::Path>();for(int i=0;i<=60;++i){geometry_msgs::PoseStamped p;p.pose.position.x=i*.05;p.pose.position.z=i<20?0.:(i<40?.1:.2);path->poses.push_back(p);}f.onReferencePath(path);auto& h=f.manager().route_height_;assert(h.ready());assert(h.points.size()==61);assert(h.times.size()==h.timed_arcs.size());assert(h.timed_arcs.front()==0.);assert(h.timed_arcs.back()==h.arcs.back());assert(h.heightAtArc(h.arcs[30])==.5);assert(h.heightAtArc(h.arcs.back())==.6000000000000001);f.retireExecution();assert(!h.ready());std::cout<<"author pathCallback -> manager height.ready, complete route and exact first/last timing mapping pass\n";}
